policies.text:
// Accesses an optional attribute without checking it first. The validator
// rejects this policy before approval; enforcement points must still deny if
// one gets through.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource) when { resource.server == "untrusted" };

// Reads the argument that the catalog declares for the tool, in the tool's record.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"agent/send_email")
when {
  context has args && context.args has "agent/send_email" && context.args["agent/send_email"] has "to:email_domain" &&
  context.args["agent/send_email"]["to:email_domain"] != "example.org"
};

// Reads the argument that the catalog declares for the tool, in the tool's record.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"agent/send_email")
when {
  context has args && context.args has "agent/send_email" && context.args["agent/send_email"] has "to:email_domain" &&
  context.args["agent/send_email"]["to:email_domain"] != "example.org"
};

// Reads the argument that the catalog declares for the tool, in the tool's record.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"agent/post_ledger")
when {
  context has args && context.args has "agent/post_ledger" && context.args["agent/post_ledger"] has "amount" &&
  context.args["agent/post_ledger"]["amount"] > 1000
};

