// Compares an integer argument with a string: the validator rejects this
// policy before approval, and its evaluation fails.
forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"agent/post_ledger")
when {
  context has args && context.args has "agent/post_ledger" && context.args["agent/post_ledger"] has "amount" &&
  context.args["agent/post_ledger"]["amount"] > "1000"
